pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));

        c.assertionDisputedCallback(bytes32(0));

        bytes32 identifier = bytes32(0);
        uint256 time = 0;
        bytes memory ancillaryData = "";
        bool success;
        vm.prank(caller);
        try c.requestPrice(identifier, time, ancillaryData) {
            success = true;
        } catch {
            success = false;
        }

        assertFalse(success);
    }
}
